import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const r="/assets/image%20(2).COOYp3fq.png",g=JSON.parse('{"title":"Action Center","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/action-center.md","filePath":"new-features/action-center.md"}'),s={name:"new-features/action-center.md"};function n(l,e,d,h,p,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="action-center" tabindex="-1">Action Center <a class="header-anchor" href="#action-center" aria-label="Permalink to &quot;Action Center&quot;">​</a></h1><h3 id="what-is-action-center" tabindex="-1">What is Action Center? <a class="header-anchor" href="#what-is-action-center" aria-label="Permalink to &quot;What is Action Center?&quot;">​</a></h3><p><strong>Action Center</strong> is an approval queue for eligible live order requests in semi-auto mode. Supported queued orders wait for review before the approval executor sends them to the broker.</p><figure><img src="'+r+`" alt=""><figcaption></figcaption></figure><p>Think of it as a <strong>safety checkpoint</strong> between your trading strategy and your real money.</p><h3 id="why-would-you-use-it" tabindex="-1">Why Would You Use It? <a class="header-anchor" href="#why-would-you-use-it" aria-label="Permalink to &quot;Why Would You Use It?&quot;">​</a></h3><h4 id="real-world-examples" tabindex="-1">Real-World Examples <a class="header-anchor" href="#real-world-examples" aria-label="Permalink to &quot;Real-World Examples&quot;">​</a></h4><p><strong>Example 1: Testing a New Strategy</strong></p><ul><li>You wrote a Python trading bot that generates buy/sell signals</li><li>You&#39;re not 100% confident it works correctly yet</li><li>Instead of letting it trade automatically, you enable Action Center</li><li>Now every order waits for your approval - you can catch mistakes before they cost you money</li></ul><p><strong>Example 2: High-Risk Trades</strong></p><ul><li>Your strategy generates a signal to buy 1000 shares of a volatile stock</li><li>You want to review the order before it executes</li><li>Action Center lets you verify quantity, price, and timing before confirming</li></ul><p><strong>Example 3: Learning and Monitoring</strong></p><ul><li>You want to understand what signals your strategy is generating</li><li>Action Center shows you every order before execution</li><li>Great for learning how your algorithm behaves in real market conditions</li></ul><h3 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h3><h4 id="two-modes" tabindex="-1">Two Modes <a class="header-anchor" href="#two-modes" aria-label="Permalink to &quot;Two Modes&quot;">​</a></h4><p><strong>1. Auto Mode (Default) - Fully Automated</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trading Signal → Tradeboard → Broker → Order Executed</span></span>
<span class="line"><span>                (instant)</span></span></code></pre></div><p>Orders execute immediately without any manual intervention.</p><p><strong>2. Semi-Auto Mode - Manual Approval Required</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trading Signal → Tradeboard → Action Center (WAIT) → You Approve → Broker → Order Executed</span></span>
<span class="line"><span>                            (paused here)              ↓</span></span>
<span class="line"><span>                                                 You Reject → Order Cancelled</span></span></code></pre></div><p>Orders wait in Action Center for you to review and approve.</p><h3 id="step-by-step-setup" tabindex="-1">Step-by-Step Setup <a class="header-anchor" href="#step-by-step-setup" aria-label="Permalink to &quot;Step-by-Step Setup&quot;">​</a></h3><h4 id="step-1-enable-semi-auto-mode" tabindex="-1">Step 1: Enable Semi-Auto Mode <a class="header-anchor" href="#step-1-enable-semi-auto-mode" aria-label="Permalink to &quot;Step 1: Enable Semi-Auto Mode&quot;">​</a></h4><ol><li>Go to <strong>Profile</strong> → <strong>API Key</strong> page</li><li>Find <strong>&quot;Order Execution Mode&quot;</strong> section</li><li>Turn ON the toggle switch (it will turn orange)</li><li>Status changes from &quot;Auto Mode&quot; to &quot;Semi-Auto Mode&quot;</li></ol><h4 id="step-2-send-orders-from-your-strategy" tabindex="-1">Step 2: Send Orders from Your Strategy <a class="header-anchor" href="#step-2-send-orders-from-your-strategy" aria-label="Permalink to &quot;Step 2: Send Orders from Your Strategy&quot;">​</a></h4><p>Your Python code stays exactly the same:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api.placeorder({</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;apikey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;symbol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SBIN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BUY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;quantity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>But now the response will be different:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Order queued for approval in Action Center&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;semi_auto&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h4 id="step-3-review-orders-in-action-center" tabindex="-1">Step 3: Review Orders in Action Center <a class="header-anchor" href="#step-3-review-orders-in-action-center" aria-label="Permalink to &quot;Step 3: Review Orders in Action Center&quot;">​</a></h4><ol><li>Click <strong>&quot;Action Center&quot;</strong> in the main menu</li><li>You&#39;ll see a badge showing how many orders are pending</li><li>Click on &quot;Pending&quot; tab to see orders waiting for approval</li></ol><h4 id="step-4-approve-or-reject" tabindex="-1">Step 4: Approve or Reject <a class="header-anchor" href="#step-4-approve-or-reject" aria-label="Permalink to &quot;Step 4: Approve or Reject&quot;">​</a></h4><p>For each order, you can:</p><ul><li><strong>Approve</strong>: Click green &quot;Approve&quot; button → Order sends to broker</li><li><strong>Reject</strong>: Click red &quot;Reject&quot; button → Order cancelled, never sent to broker</li></ul><h3 id="what-you-can-see-in-action-center" tabindex="-1">What You Can See in Action Center <a class="header-anchor" href="#what-you-can-see-in-action-center" aria-label="Permalink to &quot;What You Can See in Action Center&quot;">​</a></h3><p>For each pending order:</p><ul><li><strong>Symbol</strong> (e.g., &quot;SBIN&quot;)</li><li><strong>Action</strong> (BUY or SELL)</li><li><strong>Quantity</strong> (e.g., 10 shares)</li><li><strong>Price</strong> (e.g., ₹625.50)</li><li><strong>Order Type</strong> (MARKET, LIMIT, etc.)</li><li><strong>When it was created</strong> (e.g., &quot;2 minutes ago&quot;)</li><li><strong>Current status</strong> (Pending, Approved, Rejected)</li></ul><h3 id="tabs-in-action-center" tabindex="-1">Tabs in Action Center <a class="header-anchor" href="#tabs-in-action-center" aria-label="Permalink to &quot;Tabs in Action Center&quot;">​</a></h3><ol><li><strong>Pending</strong> - Orders waiting for your action</li><li><strong>Approved</strong> - Orders you approved and sent to broker</li><li><strong>Rejected</strong> - Orders you declined</li><li><strong>All Orders</strong> - Complete history</li></ol><p>An <strong>Approve All</strong> control clears the whole pending queue in one action, and a pending row can also be deleted outright rather than approved or rejected. A count endpoint drives the badge in the navigation bar.</p><h3 id="special-features" tabindex="-1">Special Features <a class="header-anchor" href="#special-features" aria-label="Permalink to &quot;Special Features&quot;">​</a></h3><h4 id="auto-refresh" tabindex="-1">Auto-Refresh <a class="header-anchor" href="#auto-refresh" aria-label="Permalink to &quot;Auto-Refresh&quot;">​</a></h4><p>Socket.IO events refresh the list when pending orders are created or updated. A manual refresh control is also available.</p><h4 id="statistics-dashboard" tabindex="-1">Statistics Dashboard <a class="header-anchor" href="#statistics-dashboard" aria-label="Permalink to &quot;Statistics Dashboard&quot;">​</a></h4><p>At the top, you see:</p><ul><li>Pending Approval: 5 orders</li><li>Buy Orders: 3</li><li>Sell Orders: 2</li><li>Approved: 15</li><li>Rejected: 2</li></ul><h4 id="audit-trail" tabindex="-1">Audit Trail <a class="header-anchor" href="#audit-trail" aria-label="Permalink to &quot;Audit Trail&quot;">​</a></h4><p>Every action is logged:</p><ul><li>Who approved/rejected</li><li>When it was approved/rejected</li><li>Rejection reason (if you provide one)</li></ul><h3 id="common-questions" tabindex="-1">Common Questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common Questions&quot;">​</a></h3><h4 id="q-do-i-need-to-change-my-trading-code" tabindex="-1">Q: Do I need to change my trading code? <a class="header-anchor" href="#q-do-i-need-to-change-my-trading-code" aria-label="Permalink to &quot;Q: Do I need to change my trading code?&quot;">​</a></h4><p><strong>A:</strong> No! Your API calls stay exactly the same. Just toggle the mode in settings.</p><h4 id="q-what-happens-if-i-don-t-approve-reject-orders" tabindex="-1">Q: What happens if I don&#39;t approve/reject orders? <a class="header-anchor" href="#q-what-happens-if-i-don-t-approve-reject-orders" aria-label="Permalink to &quot;Q: What happens if I don&#39;t approve/reject orders?&quot;">​</a></h4><p><strong>A:</strong> They stay in the Pending queue indefinitely. Your strategy will keep generating signals, but they won&#39;t execute until you approve.</p><h4 id="q-can-i-switch-back-to-auto-mode-anytime" tabindex="-1">Q: Can I switch back to Auto Mode anytime? <a class="header-anchor" href="#q-can-i-switch-back-to-auto-mode-anytime" aria-label="Permalink to &quot;Q: Can I switch back to Auto Mode anytime?&quot;">​</a></h4><p><strong>A:</strong> Yes! Just toggle the switch OFF in API Key settings. New orders will execute immediately again.</p><h4 id="q-which-order-types-can-the-approval-executor-dispatch" tabindex="-1">Q: Which order types can the approval executor dispatch? <a class="header-anchor" href="#q-which-order-types-can-the-approval-executor-dispatch" aria-label="Permalink to &quot;Q: Which order types can the approval executor dispatch?&quot;">​</a></h4><p><strong>A:</strong> The approval executor dispatches seven order types:</p><ul><li>Regular orders (<code>placeorder</code>)</li><li>Smart orders (<code>placesmartorder</code>)</li><li>Basket orders (<code>basketorder</code>)</li><li>Split orders (<code>splitorder</code>)</li><li>Options orders (<code>optionsorder</code>)</li><li>Multi-leg options orders (<code>optionsmultiorder</code>)</li><li>GTT orders (<code>placegttorder</code>)</li></ul><p>Everything else bypasses the queue. Order status, order book, trade book, positions, holdings, funds, open position, and the GTT order book always execute immediately because they only read. Close-position, close-all-positions, cancel, cancel-all, modify, modify-GTT, and cancel-GTT are refused with HTTP 403 in semi-auto live mode: switch back to Auto mode to use them. Cancelling or modifying a GTT is deliberately excluded from the queue because a queued action against a GTT that has already triggered is unsafe.</p><h4 id="q-can-i-see-which-orders-my-strategy-generated-vs-which-i-approved" tabindex="-1">Q: Can I see which orders my strategy generated vs which I approved? <a class="header-anchor" href="#q-can-i-see-which-orders-my-strategy-generated-vs-which-i-approved" aria-label="Permalink to &quot;Q: Can I see which orders my strategy generated vs which I approved?&quot;">​</a></h4><p><strong>A:</strong> Yes! Each order shows:</p><ul><li>Created time (when strategy sent it)</li><li>Approved time (when you clicked Approve)</li><li>Broker order ID (after execution)</li></ul><h3 id="quick-comparison" tabindex="-1">Quick Comparison <a class="header-anchor" href="#quick-comparison" aria-label="Permalink to &quot;Quick Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Auto Mode</th><th>Semi-Auto Mode</th></tr></thead><tbody><tr><td><strong>Order Execution</strong></td><td>Immediate</td><td>After approval</td></tr><tr><td><strong>Your Involvement</strong></td><td>None</td><td>Review each order</td></tr><tr><td><strong>Safety</strong></td><td>High risk (no checks)</td><td>Low risk (manual review)</td></tr><tr><td><strong>Speed</strong></td><td>Very fast</td><td>Slower (manual)</td></tr><tr><td><strong>Best For</strong></td><td>Proven strategies</td><td>Testing, learning</td></tr></tbody></table><h3 id="when-to-use-which-mode" tabindex="-1">When to Use Which Mode <a class="header-anchor" href="#when-to-use-which-mode" aria-label="Permalink to &quot;When to Use Which Mode&quot;">​</a></h3><h4 id="use-auto-mode-when" tabindex="-1">Use Auto Mode When: <a class="header-anchor" href="#use-auto-mode-when" aria-label="Permalink to &quot;Use Auto Mode When:&quot;">​</a></h4><ul><li>Your strategy is proven and tested</li><li>You need high-frequency trading</li><li>You trust the strategy 100%</li><li>Speed is critical</li></ul><h4 id="use-semi-auto-mode-when" tabindex="-1">Use Semi-Auto Mode When: <a class="header-anchor" href="#use-semi-auto-mode-when" aria-label="Permalink to &quot;Use Semi-Auto Mode When:&quot;">​</a></h4><ul><li>Testing a new strategy</li><li>Learning algorithmic trading</li><li>High-risk trades need verification</li><li>You want full control over every order</li></ul><h3 id="example-workflow" tabindex="-1">Example Workflow <a class="header-anchor" href="#example-workflow" aria-label="Permalink to &quot;Example Workflow&quot;">​</a></h3><p><strong>Scenario</strong>: You&#39;re testing a new momentum strategy</p><ol><li><strong>Morning 9:00 AM</strong><ul><li>Enable Semi-Auto mode in settings</li><li>Start your Python trading bot</li></ul></li><li><strong>9:30 AM</strong> - Market opens <ul><li>Your bot generates BUY signal for RELIANCE</li><li>Order appears in Action Center &quot;Pending&quot; tab</li></ul></li><li><strong>9:31 AM</strong> - You review <ul><li>Symbol: RELIANCE (correct)</li><li>Quantity: 10 (looks right)</li><li>Price: ₹2,500 (reasonable)</li><li>Click &quot;Approve&quot;</li></ul></li><li><strong>9:31 AM</strong> - Order executes <ul><li>Sent to broker</li><li>Shows &quot;Approved&quot; status</li><li>Broker order ID: 240612000123456</li></ul></li><li><strong>10:00 AM</strong> - Another signal <ul><li>Your bot wants to SELL 100 shares of INFY</li><li>Wait... 100 shares seems too much!</li><li>Click &quot;Reject&quot; with reason: &quot;Quantity too large&quot;</li></ul></li><li><strong>End of Day</strong><ul><li>Review statistics: 10 approved, 2 rejected</li><li>Adjust your strategy code to fix the quantity issue</li></ul></li></ol><h3 id="tips-for-success" tabindex="-1">Tips for Success <a class="header-anchor" href="#tips-for-success" aria-label="Permalink to &quot;Tips for Success&quot;">​</a></h3><ol><li><strong>Start with Semi-Auto</strong> when testing new strategies</li><li><strong>Switch to Auto</strong> only when you&#39;re confident</li><li><strong>Monitor the Pending tab</strong> regularly (it auto-refreshes)</li><li><strong>Use rejection reasons</strong> to track why you rejected orders</li><li><strong>Review history</strong> in &quot;All Orders&quot; tab to learn from patterns</li></ol><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h3><hr><p><strong>Remember</strong>: Action Center gives you control. Use it wisely to protect your capital while testing new strategies!</p>`,78)])])}const k=t(s,[["render",n]]);export{g as __pageData,k as default};
